DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='optitrace_app') THEN CREATE ROLE optitrace_app NOLOGIN; END IF; END $$;
CREATE TABLE tenants(id text PRIMARY KEY,name text NOT NULL);
CREATE TABLE users(id text PRIMARY KEY,email text NOT NULL UNIQUE);
CREATE TABLE memberships(id text PRIMARY KEY,tenant_id text REFERENCES tenants(id),user_id text REFERENCES users(id),roles text[] NOT NULL,UNIQUE(tenant_id,user_id));
CREATE TABLE invitations(id text PRIMARY KEY,tenant_id text REFERENCES tenants(id),email text NOT NULL,roles text[] NOT NULL,accepted_by text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(hash text PRIMARY KEY,user_id text REFERENCES users(id),csrf text NOT NULL,expires_at timestamptz NOT NULL,provider_token text NOT NULL DEFAULT '',provider_checked timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_transactions(hash text PRIMARY KEY,nonce text NOT NULL,verifier text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE resources(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),kind text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE credentials(id text PRIMARY KEY,tenant_id text REFERENCES tenants(id),name text NOT NULL,hash text NOT NULL UNIQUE,scopes text[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked boolean NOT NULL DEFAULT false);
CREATE TABLE audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id text NOT NULL,actor_id text NOT NULL,action text NOT NULL,resource_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),seed bigint NOT NULL,count integer NOT NULL CHECK(count BETWEEN 1 AND 1000),status text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,lease_until timestamptz,lease_token text,result jsonb,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency(tenant_id text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb,PRIMARY KEY(tenant_id,key));
CREATE FUNCTION current_tenant() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.tenant_id',true),'') $$;
ALTER TABLE resources ENABLE ROW LEVEL SECURITY;
ALTER TABLE resources FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_resources ON resources USING(tenant_id=current_tenant()) WITH CHECK(tenant_id=current_tenant());
ALTER TABLE audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_audit ON audit USING(tenant_id=current_tenant()) WITH CHECK(tenant_id=current_tenant());
ALTER TABLE idempotency ENABLE ROW LEVEL SECURITY;
ALTER TABLE idempotency FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_idempotency ON idempotency USING(tenant_id=current_tenant()) WITH CHECK(tenant_id=current_tenant());
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_memberships ON memberships USING(tenant_id=current_tenant()) WITH CHECK(tenant_id=current_tenant());
ALTER TABLE invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_invitations ON invitations USING(tenant_id=current_tenant()) WITH CHECK(tenant_id=current_tenant());
ALTER TABLE credentials ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_credentials ON credentials USING(tenant_id=current_tenant()) WITH CHECK(tenant_id=current_tenant());
ALTER TABLE jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_jobs ON jobs USING(tenant_id=current_tenant()) WITH CHECK(tenant_id=current_tenant());
CREATE FUNCTION auth_memberships(uid text) RETURNS TABLE(id text,name text,roles text[]) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT t.id,t.name,m.roles FROM memberships m JOIN tenants t ON t.id=m.tenant_id WHERE m.user_id=uid $$;
CREATE FUNCTION auth_credential(h text) RETURNS TABLE(id text,tenant_id text,scopes text[]) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT c.id,c.tenant_id,c.scopes FROM credentials c WHERE c.hash=h AND NOT c.revoked $$;
CREATE FUNCTION auth_accept(uid text,mail text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM memberships WHERE user_id=uid) AND NOT EXISTS(SELECT 1 FROM invitations WHERE lower(email)=lower(mail) AND accepted_by IS NULL) THEN RETURN false; END IF;
 INSERT INTO users(id,email) VALUES(uid,mail) ON CONFLICT(id) DO UPDATE SET email=EXCLUDED.email;
 INSERT INTO memberships(id,tenant_id,user_id,roles) SELECT id,tenant_id,uid,roles FROM invitations WHERE lower(email)=lower(mail) AND accepted_by IS NULL ON CONFLICT(tenant_id,user_id) DO NOTHING;
 UPDATE invitations SET accepted_by=uid WHERE lower(email)=lower(mail) AND accepted_by IS NULL;
 RETURN true; END $$;
CREATE FUNCTION claim_job(token text) RETURNS TABLE(id text,seed bigint,count integer) LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ UPDATE jobs j SET status='running',attempts=j.attempts+1,lease_until=now()+interval '11 minutes',lease_token=token,error=NULL WHERE j.id=(SELECT q.id FROM jobs q WHERE (q.status='queued' OR (q.status='running' AND q.lease_until<now())) AND q.attempts<3 ORDER BY q.created_at FOR UPDATE SKIP LOCKED LIMIT 1) RETURNING j.id,j.seed,j.count $$;
CREATE FUNCTION finish_job(jid text,token text,payload jsonb,err text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 UPDATE jobs SET status=CASE WHEN err IS NULL THEN 'completed' WHEN attempts<3 THEN 'queued' ELSE 'failed' END,result=payload,error=err,lease_until=NULL WHERE id=jid AND lease_token=token AND status='running';
 END $$;
CREATE FUNCTION expire_jobs() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ UPDATE jobs SET status='failed',error='Worker lease expired after three attempts' WHERE status='running' AND lease_until<now() AND attempts>=3 $$;
REVOKE ALL ON FUNCTION auth_memberships(text),auth_credential(text),auth_accept(text,text),claim_job(text),finish_job(text,text,jsonb,text),expire_jobs() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION auth_memberships(text),auth_credential(text),auth_accept(text,text),claim_job(text),finish_job(text,text,jsonb,text),expire_jobs() TO optitrace_app;
CREATE FUNCTION immutable_policy() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.kind='policy' AND OLD.data->>'status' IN ('approved','active') AND (NEW.data - 'status') IS DISTINCT FROM (OLD.data - 'status') THEN RAISE EXCEPTION 'approved policy immutable'; END IF;
 IF NEW.kind='policy' AND NEW.data->>'status' IN ('approved','active') AND (NEW.data->>'reviewer_id' IS NULL OR NEW.data->>'author_id'=NEW.data->>'reviewer_id') THEN RAISE EXCEPTION 'independent reviewer required'; END IF;
 IF OLD.kind='policy' AND OLD.data->>'status'='active' AND NEW.data->>'status'<>'active' THEN RAISE EXCEPTION 'active policy immutable'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER policy_immutable BEFORE UPDATE ON resources FOR EACH ROW EXECUTE FUNCTION immutable_policy();
CREATE FUNCTION immutable_resource() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.kind='evaluation' OR (TG_OP='DELETE' AND OLD.kind='policy' AND OLD.data->>'status' IN ('approved','active')) THEN RAISE EXCEPTION 'immutable evidence or approved policy'; END IF; RETURN OLD; END $$;
CREATE TRIGGER resource_delete_guard BEFORE DELETE ON resources FOR EACH ROW EXECUTE FUNCTION immutable_resource();
CREATE TRIGGER trace_update_guard BEFORE UPDATE ON resources FOR EACH ROW WHEN (OLD.kind='evaluation') EXECUTE FUNCTION immutable_resource();
GRANT USAGE ON SCHEMA public TO optitrace_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON tenants,users,memberships,invitations,sessions,resources,credentials,jobs,idempotency,login_transactions TO optitrace_app;
GRANT SELECT,INSERT ON audit TO optitrace_app;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO optitrace_app;
